# owner: platform
"""Seating charts: students sorted by last name, in rows."""

from typing import List, Sequence

from rosterkit.models import Student

Roster = Sequence[Student]


def _sort_key(student: Student) -> tuple:
    last = student.last_name.casefold()
    return (last, student.first_name.casefold())


def _check_input(students: Sequence, seats: int) -> None:
    if seats < 1:
        raise ValueError(f"seats must be positive: {seats}")
    if not students:
        raise ValueError("no students to seat")


def _chunks(names: List[str], size: int) -> List[List[str]]:
    return [
        names[start : start + size]
        for start in range(0, len(names), size)
    ]


def _row_text(number: int, names: List[str]) -> str:
    return f"Row {number}: " + " | ".join(names)


# ---
def seat_rows(students: Roster, seats: int) -> List[str]:
    """One text line per row, sorted by last name."""
    _check_input(students, seats)
    ordered = sorted(students, key=_sort_key)
    names = [item.display_name for item in ordered]
    rows = enumerate(_chunks(names, seats), 1)
    return [_row_text(*entry) for entry in rows]
